        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(extract_values(v))
        elif isinstance(obj, list):
            for item in obj:
                values.extend(extract_values(item))
        else:
            values.append(obj)
        return values
    all_values = extract_values(processed)
    value_counts = Counter(all_values)
    return {"data": processed, "value_counts": value_counts}
